'use client';

import { memo, useCallback, useState } from 'react';

import { useDocumentVisible } from '@/registry/ndeko/hooks/use-agent-run';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { ArrowRightIcon } from '@/registry/ndeko/lib/icons';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { ACTIVITY_TITLE, AGENTS, regionOf, type RegionId } from './data';
import { GlobeStage } from './globe-stage';
import { RegionList } from './region-list';
import {
  facingLineOf,
  handoffLineOf,
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  totalRunsOf,
  type Handoff,
} from './session';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const ARROW_KEYS = new Set(['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown']);

/** The latest hand-off, under the globe, so the arc says what it is. It stays on one line. */
const HandoffLine = memo(function HandoffLine({
  handoff,
}: {
  handoff: Handoff;
}) {
  const agent = AGENTS[handoff.agentId];
  const color = seriesColorOf(agent.series);
  const line = handoffLineOf(handoff);
  const from = regionOf(handoff.from).name;
  const to = regionOf(handoff.to).name;

  return (
    <p className='text-muted-foreground flex h-5 items-center justify-center text-xs whitespace-nowrap'>
      <span className='sr-only'>{line}</span>
      <Swap swapKey={line}>
        <span aria-hidden='true' className='flex items-center'>
          <MeshTile
            seed={agent.name}
            color={color}
            size='sm'
            className='me-1.5'
          />
          <span className='text-foreground me-1.5 font-medium'>
            {agent.name}
          </span>
          {from}
          <ArrowRightIcon className='mx-1 size-3' />
          {to}
        </span>
      </Swap>
    </p>
  );
});

export default function Maps01() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const isVisible = useDocumentVisible();
  const [releasedId, setReleasedId] = useState<RegionId | null>(null);
  const isOnScreen = isInView && isVisible;
  const isHeld = releasedId !== state.selectedId;
  const total = totalRunsOf(state);
  const canReplay = isFinished && !isAutoplaying;
  const message = spokenUnless(isAutoplaying, state.notice);
  const facingLine = facingLineOf(state.facing);
  const globeLabel = `Globe of agent activity, ${facingLine}`;

  const pick = useCallback(
    (id: RegionId) => {
      setReleasedId(null);
      act({ type: 'selected', id });
    },
    [act]
  );

  function letGo() {
    setReleasedId(state.selectedId);
  }

  function letGoOnArrows(event: React.KeyboardEvent<HTMLDivElement>) {
    if (ARROW_KEYS.has(event.key)) {
      letGo();
    }
  }

  function replay() {
    setReleasedId(null);
    restart();
  }

  return (
    <div
      ref={ref}
      className='bg-background text-foreground @container min-h-dvh w-full'
    >
      <div className='mx-auto flex max-w-5xl flex-col gap-5 p-4 @3xl:gap-6 @3xl:p-8'>
        <header className='flex flex-wrap items-center gap-x-3 gap-y-2'>
          <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
            <h1 className='text-lg font-semibold text-balance'>
              {ACTIVITY_TITLE}
            </h1>
            <p className='text-muted-foreground flex flex-wrap items-center gap-x-2 gap-y-1 text-xs'>
              Live runs, tokens and spend by region
              <Badge variant='secondary'>Illustrative</Badge>
            </p>
          </div>
          <ReplayButton
            isShown={canReplay}
            onReplay={replay}
            label='Replay the activity'
          />
        </header>

        <div className='grid grid-cols-1 items-center gap-6 @3xl:grid-cols-2 @3xl:gap-8'>
          <div className='flex min-w-0 flex-col items-center gap-3'>
            <div
              onPointerDown={letGo}
              onKeyDown={letGoOnArrows}
              className='relative aspect-square w-full max-w-[17rem] @md:max-w-[20rem] @3xl:max-w-[26rem]'
            >
              <div
                aria-hidden='true'
                className='bg-foreground/[0.04] absolute inset-[10%] rounded-full'
              />
              <GlobeStage
                selectedId={state.selectedId}
                handoff={state.lastHandoff}
                drawingId={state.drawingId}
                facing={state.facing}
                isHeld={isHeld}
                isActive={isOnScreen}
                label={globeLabel}
              />
            </div>
            <HandoffLine handoff={state.lastHandoff} />
          </div>
          <RegionList
            loads={state.loads}
            selectedId={state.selectedId}
            total={total}
            pressed={pressed}
            onSelect={pick}
          />
        </div>
      </div>
      <LiveRegion message={message} />
    </div>
  );
}

'use client';

import { memo, useEffect, useMemo, useState } from 'react';

import {
  Globe,
  type GlobeArc,
  type GlobeLocation,
  type GlobeMarker,
} from '@/components/core/globe';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

import { regionOf, type RegionId } from './data';
import { drawnShareOf, pointAlong } from './geo';
import {
  facingKeyOf,
  facingLocationOf,
  handoffKeyOf,
  regionsInViewOf,
  type Facing,
  type Handoff,
} from './session';

/** The globe has come most of the way to a new view this long after it starts to turn. */
const TURN_LEAD_MS = 600;

/** An arc draws itself in a few steps, one render each, while the globe settles: never one render a frame. */
const DRAW_STEPS = 6;

const STEP_MS = 50;

const PICKED_MARKER = 0.075;

const REGION_MARKER = 0.05;

/** Close to the latitude of the views, so the globe barely tilts when it first faces one. */
const STARTING_TILT = 30;

const NO_ARCS: GlobeArc[] = [];

type Settled = {
  key: string;
  location: GlobeLocation;
};

/**
 * The globe starts on the meridian ninety degrees west, tilted as asked, and still has to turn to
 * its first view: even the first arc waits for it.
 */
const STARTING_VIEW: Settled = { key: '', location: [STARTING_TILT, -90] };

type Drawing = {
  id: number | null;
  step: number;
};

function markerSizeOf(isPicked: boolean) {
  if (isPicked) {
    return PICKED_MARKER;
  }
  return REGION_MARKER;
}

/** Only the regions near the centre of the view the globe leaves and of the one it turns to. */
function markersOf(
  selectedId: RegionId,
  target: GlobeLocation,
  previous: GlobeLocation
): GlobeMarker[] {
  const regions = regionsInViewOf(target, previous);
  return regions.map((region) => {
    const isPicked = region.id === selectedId;
    return {
      location: region.location,
      size: markerSizeOf(isPicked),
      label: `${region.name}, ${region.place}`,
    };
  });
}

function arcOf(handoff: Handoff, drawing: Drawing): GlobeArc | null {
  const from = regionOf(handoff.from).location;
  const to = regionOf(handoff.to).location;
  const isDrawing = handoff.id === drawing.id;
  const isWhole = !isDrawing || drawing.step >= DRAW_STEPS;
  if (isWhole) {
    return { from, to };
  }
  if (drawing.step === 0) {
    return null;
  }
  const progress = drawing.step / DRAW_STEPS;
  const share = drawnShareOf(progress);
  const end = pointAlong(from, to, share);
  return { from, to: end };
}

/** The arc of the last hand-off, only while the globe faces its route: from elsewhere it would cross the rim. */
function arcsOf(handoff: Handoff, drawing: Drawing, isFramed: boolean) {
  if (!isFramed) {
    return NO_ARCS;
  }
  const arc = arcOf(handoff, drawing);
  if (!arc) {
    return NO_ARCS;
  }
  return [arc];
}

function grown(drawing: Drawing): Drawing {
  const next = drawing.step + 1;
  const step = Math.min(next, DRAW_STEPS);
  return { id: drawing.id, step };
}

/** Under reduced motion an arc is whole as soon as its hand-off happens. */
function firstStepOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return DRAW_STEPS;
  }
  return 0;
}

/** A globe a person turned by hand stays where they left it until a region is picked again. */
function focusOf(isHeld: boolean, target: GlobeLocation) {
  if (isHeld) {
    return target;
  }
  return null;
}

export type GlobeStageProps = {
  selectedId: RegionId;
  handoff: Handoff;
  drawingId: number | null;
  facing: Facing;
  /** False once a person turned the globe by hand. */
  isHeld: boolean;
  /** Nothing turns or draws while the block is off screen or the tab is hidden. */
  isActive: boolean;
  label: string;
};

/**
 * The globe draws frames only while it turns, and an arc draws itself in a few renders once the
 * globe has nearly arrived. Between two beats nothing here renders, and the globe stays still.
 */
export const GlobeStage = memo(function GlobeStage({
  selectedId,
  handoff,
  drawingId,
  facing,
  isHeld,
  isActive,
  label,
}: GlobeStageProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const facingKey = facingKeyOf(facing);
  const target = useMemo(() => facingLocationOf(facing), [facing]);
  const [settled, setSettled] = useState<Settled>(STARTING_VIEW);
  const [drawing, setDrawing] = useState<Drawing>({
    id: drawingId,
    step: DRAW_STEPS,
  });
  const isNewDrawing = drawing.id !== drawingId;
  if (isNewDrawing) {
    setDrawing({ id: drawingId, step: firstStepOf(shouldReduceMotion) });
  }
  const isTurning = settled.key !== facingKey;
  const arrivesAtOnce = isTurning && shouldReduceMotion;
  if (arrivesAtOnce) {
    setSettled({ key: facingKey, location: target });
  }
  const routeKey = handoffKeyOf(handoff);
  const facesRoute = facingKey === routeKey;
  const hasArrived = settled.key === routeKey;
  const isFramed = isHeld && facesRoute && hasArrived;
  const hasDrawing = drawing.id !== null;
  const isUnfinished = hasDrawing && drawing.step < DRAW_STEPS;
  const canDraw = isActive && isFramed;
  const isGrowing = canDraw && isUnfinished;

  useEffect(() => {
    if (!isTurning || !isActive) {
      return;
    }
    const arrival: Settled = { key: facingKey, location: target };
    const timer = setTimeout(() => setSettled(arrival), TURN_LEAD_MS);
    return () => clearTimeout(timer);
  }, [isTurning, isActive, facingKey, target]);

  useEffect(() => {
    if (!isGrowing) {
      return;
    }
    const timer = setTimeout(() => setDrawing(grown), STEP_MS);
    return () => clearTimeout(timer);
  }, [isGrowing, drawing.step]);

  const markers = useMemo(
    () => markersOf(selectedId, target, settled.location),
    [selectedId, target, settled.location]
  );
  const arcs = useMemo(
    () => arcsOf(handoff, drawing, isFramed),
    [handoff, drawing, isFramed]
  );
  const focus = useMemo(() => focusOf(isHeld, target), [isHeld, target]);

  return (
    <Globe
      markers={markers}
      arcs={arcs}
      focus={focus}
      autoRotate={false}
      tilt={STARTING_TILT}
      label={label}
    />
  );
});

'use client';

import { memo } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';

import { REGIONS, type Region, type RegionId, type RegionLoad } from './data';

/** A row is 48px tall with 2px below it: the highlight travels this far a row, on transform alone. */
const ROW_PITCH_PX = 50;

const ROW = [
  'flex h-12 w-full cursor-pointer items-center gap-2.5 rounded-lg px-2.5 text-start outline-none',
  'transition-[background-color,scale] duration-150 ease-(--ease-out-strong) active:scale-[0.98]',
  'hover:bg-foreground/[0.03] focus-visible:ring-ring/25 focus-visible:ring-[3px]',
].join(' ');

const HIGHLIGHT =
  'bg-foreground/[0.06] pointer-events-none absolute inset-x-0 top-0 h-12 rounded-lg transition-transform duration-200 ease-(--ease-out-strong)';

const FIGURE = 'shrink-0 justify-end text-[13px]';

const SPEND: Intl.NumberFormatOptions = {
  style: 'currency',
  currency: 'USD',
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
};

const SPEND_TEXT = new Intl.NumberFormat('en-US', SPEND);

function runsWordOf(count: number) {
  if (count === 1) {
    return '1 run';
  }
  return `${count} runs`;
}

function liveWordOf(count: number) {
  if (count === 1) {
    return 'run live';
  }
  return 'runs live';
}

function regionsWordOf(count: number) {
  if (count === 1) {
    return '1 region';
  }
  return `${count} regions`;
}

function totalLineOf(total: number) {
  const live = liveWordOf(total);
  const regions = regionsWordOf(REGIONS.length);
  return `${live} in ${regions}`;
}

function dollarsOf(cents: number) {
  return cents / 100;
}

/** Europe, Frankfurt: 11 runs, 140k tokens a minute, $7.10 an hour. */
function spokenOf(region: Region, load: RegionLoad) {
  const runs = runsWordOf(load.runs);
  const dollars = dollarsOf(load.cents);
  const spend = SPEND_TEXT.format(dollars);
  const place = `${region.name}, ${region.place}`;
  return `${place}: ${runs}, ${load.tokens}k tokens a minute, ${spend} an hour`;
}

function dotOf(isPicked: boolean) {
  if (isPicked) {
    return 'bg-primary';
  }
  return 'bg-foreground/25';
}

function highlightStyleOf(selectedId: RegionId) {
  const index = REGIONS.findIndex((region) => region.id === selectedId);
  const row = Math.max(index, 0);
  const offset = row * ROW_PITCH_PX;
  return { transform: `translateY(${offset}px)` };
}

type RegionRowProps = {
  region: Region;
  load: RegionLoad;
  isPicked: boolean;
  isPressed: boolean;
  onSelect: (id: RegionId) => void;
};

/** A row renders again only when its own figures, its pick or its press change. */
const RegionRow = memo(function RegionRow({
  region,
  load,
  isPicked,
  isPressed,
  onSelect,
}: RegionRowProps) {
  const spend = dollarsOf(load.cents);

  return (
    <li>
      <button
        type='button'
        aria-pressed={isPicked}
        aria-label={spokenOf(region, load)}
        onClick={() => onSelect(region.id)}
        className={cn(ROW, pressedQuietOf(isPressed))}
      >
        <span
          aria-hidden='true'
          className={cn(
            'size-2 shrink-0 rounded-full transition-colors duration-150',
            dotOf(isPicked)
          )}
        />
        <span className='flex min-w-0 flex-1 flex-col'>
          <span className='truncate text-[13px] leading-5 font-medium'>
            {region.name}
          </span>
          <span className='text-muted-foreground truncate text-xs leading-4'>
            {region.place}
          </span>
        </span>
        <MotionNumber value={load.runs} className={cn(FIGURE, 'w-9')} />
        <MotionNumber
          value={load.tokens}
          suffix='k'
          className={cn(FIGURE, 'w-12')}
        />
        <MotionNumber
          value={spend}
          format={SPEND}
          className={cn(FIGURE, 'w-14')}
        />
      </button>
    </li>
  );
});

const TotalLine = memo(function TotalLine({ total }: { total: number }) {
  return (
    <p className='flex flex-wrap items-baseline gap-x-2 px-2.5 pt-1.5 pb-3'>
      <MotionNumber
        value={total}
        className='text-2xl leading-8 font-semibold'
      />
      <span className='text-muted-foreground text-xs'>
        {totalLineOf(total)}
      </span>
    </p>
  );
});

export type RegionListProps = {
  loads: Record<RegionId, RegionLoad>;
  selectedId: RegionId;
  total: number;
  /** The region a demonstration picks, shown held down. */
  pressed: string | null;
  onSelect: (id: RegionId) => void;
};

/** One row per region: picking one turns the globe to it, and its figures roll as runs come and go. */
export function RegionList({
  loads,
  selectedId,
  total,
  pressed,
  onSelect,
}: RegionListProps) {
  return (
    <section
      aria-label='Regions'
      className='bg-card hairline-ring ring-border dark:bg-foreground/[0.04] flex min-w-0 flex-col rounded-xl p-2 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
    >
      <TotalLine total={total} />
      <div
        aria-hidden='true'
        className='text-muted-foreground flex items-center gap-2.5 px-2.5 pb-1 text-xs'
      >
        <span className='size-2 shrink-0' />
        <span className='min-w-0 flex-1'>Region</span>
        <span className='w-9 shrink-0 text-end'>Runs</span>
        <span className='w-12 shrink-0 text-end'>Tokens</span>
        <span className='w-14 shrink-0 text-end'>Spend</span>
      </div>
      <div className='relative'>
        <span
          aria-hidden='true'
          style={highlightStyleOf(selectedId)}
          className={HIGHLIGHT}
        />
        <ul className='relative flex flex-col gap-0.5'>
          {REGIONS.map((region) => (
            <RegionRow
              key={region.id}
              region={region}
              load={loads[region.id]}
              isPicked={region.id === selectedId}
              isPressed={pressed === `region-${region.id}`}
              onSelect={onSelect}
            />
          ))}
        </ul>
      </div>
      <p className='text-muted-foreground px-2.5 pt-2 pb-1 text-xs'>
        Tokens a minute and spend an hour, as they stand now
      </p>
    </section>
  );
}

import type { GlobeLocation } from '@/components/core/globe';

type Vector = [x: number, y: number, z: number];

/** Two places this close, or exactly opposite, have no single path between them to follow. */
const SAME_PLACE = 0.0001;

/**
 * How far to the south of a route the globe looks from. Seen from a point on the route, an arc runs
 * through the centre as a straight line; seen from here it bows over the surface, and both ends of a
 * route of sixty degrees sit about thirty-five degrees from the centre, well inside the disk.
 */
const ROUTE_VIEW_ASIDE_DEG = 20;

/** A picked region sits this far above the centre, so an arc that leaves it bows instead of running straight. */
const REGION_VIEW_SOUTH_DEG = 15;

/**
 * The globe draws its markers a little above the sphere and hides only those behind the disk, so a
 * marker near the rim, or just past it, is drawn outside the disk. One shows only this close to the
 * centre of a view, which keeps the largest dot inside the disk up to about sixty-eight degrees.
 */
const MARKER_REACH_DEG = 60;

function radiansOf(degrees: number) {
  const halfTurns = degrees / 180;
  return halfTurns * Math.PI;
}

function degreesOf(radians: number) {
  const halfTurns = radians / Math.PI;
  return halfTurns * 180;
}

function vectorOf([latitude, longitude]: GlobeLocation): Vector {
  const latitudeAngle = radiansOf(latitude);
  const longitudeAngle = radiansOf(longitude);
  const ring = Math.cos(latitudeAngle);
  const x = ring * Math.cos(longitudeAngle);
  const y = ring * Math.sin(longitudeAngle);
  const z = Math.sin(latitudeAngle);
  return [x, y, z];
}

/** Rounding can push a sine or a cosine a hair past 1, where the inverse functions give no answer. */
function withinUnit(value: number) {
  const atMostOne = Math.min(1, value);
  return Math.max(-1, atMostOne);
}

function locationOf([x, y, z]: Vector): GlobeLocation {
  const height = withinUnit(z);
  const latitudeAngle = Math.asin(height);
  const longitudeAngle = Math.atan2(y, x);
  const latitude = degreesOf(latitudeAngle);
  const longitude = degreesOf(longitudeAngle);
  return [latitude, longitude];
}

function alignmentOf(first: Vector, second: Vector) {
  const alongX = first[0] * second[0];
  const alongY = first[1] * second[1];
  const alongZ = first[2] * second[2];
  const flat = alongX + alongY;
  return flat + alongZ;
}

function sumOf(first: Vector, second: Vector): Vector {
  const x = first[0] + second[0];
  const y = first[1] + second[1];
  const z = first[2] + second[2];
  return [x, y, z];
}

function scaledOf([x, y, z]: Vector, factor: number): Vector {
  const scaledX = x * factor;
  const scaledY = y * factor;
  const scaledZ = z * factor;
  return [scaledX, scaledY, scaledZ];
}

/** A route with no length has no direction: it stays at zero instead of dividing by it. */
function unitOf(vector: Vector): Vector {
  const length = Math.hypot(...vector);
  if (length === 0) {
    return vector;
  }
  return scaledOf(vector, 1 / length);
}

function crossOf(first: Vector, second: Vector): Vector {
  const xUp = first[1] * second[2];
  const xDown = first[2] * second[1];
  const yUp = first[2] * second[0];
  const yDown = first[0] * second[2];
  const zUp = first[0] * second[1];
  const zDown = first[1] * second[0];
  const x = xUp - xDown;
  const y = yUp - yDown;
  const z = zUp - zDown;
  return [x, y, z];
}

function blend(
  start: number,
  end: number,
  startWeight: number,
  endWeight: number
) {
  const fromStart = start * startWeight;
  const fromEnd = end * endWeight;
  return fromStart + fromEnd;
}

/** The point a share of the way from one place to another, along the shortest path over the globe. */
export function pointAlong(
  from: GlobeLocation,
  to: GlobeLocation,
  share: number
): GlobeLocation {
  const start = vectorOf(from);
  const end = vectorOf(to);
  const alignment = alignmentOf(start, end);
  const bounded = withinUnit(alignment);
  const angle = Math.acos(bounded);
  const spread = Math.sin(angle);
  if (spread < SAME_PLACE) {
    return to;
  }
  const rest = 1 - share;
  const startAngle = rest * angle;
  const endAngle = share * angle;
  const startTurn = Math.sin(startAngle);
  const endTurn = Math.sin(endAngle);
  const startWeight = startTurn / spread;
  const endWeight = endTurn / spread;
  const x = blend(start[0], end[0], startWeight, endWeight);
  const y = blend(start[1], end[1], startWeight, endWeight);
  const z = blend(start[2], end[2], startWeight, endWeight);
  return locationOf([x, y, z]);
}

/** Fast at the start and slow at the end, the way a line is drawn by hand. */
export function drawnShareOf(progress: number) {
  const left = 1 - progress;
  const leftCubed = left ** 3;
  return 1 - leftCubed;
}

/** The pole of the circle a route runs along, taken on its southern side. */
function southSideOf(start: Vector, end: Vector): Vector {
  const across = crossOf(start, end);
  const pole = unitOf(across);
  const isNorthern = pole[2] > 0;
  if (isNorthern) {
    return scaledOf(pole, -1);
  }
  return pole;
}

/** Where the globe looks from to show a route: past its middle, a little to its south. */
export function routeViewOf(from: GlobeLocation, to: GlobeLocation) {
  const start = vectorOf(from);
  const end = vectorOf(to);
  const sum = sumOf(start, end);
  const middle = unitOf(sum);
  const side = southSideOf(start, end);
  const aside = radiansOf(ROUTE_VIEW_ASIDE_DEG);
  const middleShare = Math.cos(aside);
  const sideShare = Math.sin(aside);
  const fromMiddle = scaledOf(middle, middleShare);
  const fromSide = scaledOf(side, sideShare);
  const view = sumOf(fromMiddle, fromSide);
  return locationOf(view);
}

export function regionViewOf([latitude, longitude]: GlobeLocation) {
  const southern = latitude - REGION_VIEW_SOUTH_DEG;
  const view: GlobeLocation = [southern, longitude];
  return view;
}

/** The angle between two places, seen from the centre of the earth, in degrees. */
export function degreesApartOf(first: GlobeLocation, second: GlobeLocation) {
  const start = vectorOf(first);
  const end = vectorOf(second);
  const alignment = alignmentOf(start, end);
  const bounded = withinUnit(alignment);
  const angle = Math.acos(bounded);
  return degreesOf(angle);
}

export function isNearCentreOf(location: GlobeLocation, view: GlobeLocation) {
  const apart = degreesApartOf(location, view);
  return apart <= MARKER_REACH_DEG;
}

import type { GlobeLocation } from '@/components/core/globe';
import type { SessionStep } from '@/registry/ndeko/hooks/use-session';

import {
  AGENTS,
  LOADS,
  regionOf,
  REGIONS,
  type AgentId,
  type Region,
  type RegionId,
  type RegionLoad,
} from './data';
import { isNearCentreOf, regionViewOf, routeViewOf } from './geo';

/** What one run carries while it lives in a region: thousands of tokens a minute and cents an hour. */
export type RunRate = {
  tokens: number;
  cents: number;
};

export type Handoff = {
  id: number;
  agentId: AgentId;
  from: RegionId;
  to: RegionId;
};

/** What the globe turns to: the region picked last, or the route of the hand-off that just happened. */
export type Facing =
  | { kind: 'region'; id: RegionId }
  | { kind: 'route'; from: RegionId; to: RegionId };

export type ActivityState = {
  selectedId: RegionId;
  loads: Record<RegionId, RegionLoad>;
  lastHandoff: Handoff;
  /** The hand-off whose arc still has to draw itself. Null while the arc on the globe is whole. */
  drawingId: number | null;
  facing: Facing;
  nextId: number;
  /** The last change, said to screen readers. */
  notice: string;
};

export type ActivityAction =
  | { type: 'selected'; id: RegionId }
  | { type: 'started'; region: RegionId; rate: RunRate }
  | { type: 'finished'; region: RegionId; rate: RunRate }
  | {
      type: 'handedOff';
      agentId: AgentId;
      from: RegionId;
      to: RegionId;
      rate: RunRate;
    };

type Step = SessionStep<ActivityState, ActivityAction>;

type Sign = 1 | -1;

/** The hand-off a round ends on: a new round starts where the last one stopped, so the loop never shows. */
const LAST_HANDOFF: Handoff = {
  id: 1,
  agentId: 'coder',
  from: 'us-east',
  to: 'europe',
};

export const INITIAL: ActivityState = {
  selectedId: 'us-east',
  loads: LOADS,
  lastHandoff: LAST_HANDOFF,
  drawingId: null,
  facing: { kind: 'route', from: 'us-east', to: 'europe' },
  nextId: LAST_HANDOFF.id + 1,
  notice: '',
};

/** A route reads the same both ways, so a hand-off back along it needs no turn. */
function routeKeyOf(from: RegionId, to: RegionId) {
  const ends = [from, to];
  ends.sort();
  return `route:${ends.join(':')}`;
}

export function facingKeyOf(facing: Facing) {
  if (facing.kind === 'region') {
    return `region:${facing.id}`;
  }
  return routeKeyOf(facing.from, facing.to);
}

export function handoffKeyOf(handoff: Handoff) {
  return routeKeyOf(handoff.from, handoff.to);
}

export function facingLocationOf(facing: Facing): GlobeLocation {
  if (facing.kind === 'region') {
    const region = regionOf(facing.id);
    return regionViewOf(region.location);
  }
  const from = regionOf(facing.from).location;
  const to = regionOf(facing.to).location;
  return routeViewOf(from, to);
}

/**
 * The regions whose marker the globe may draw while it turns from one view to the next: close to
 * the centre of both, so on the front of the sphere and inside the disk the whole way.
 */
export function regionsInViewOf(
  target: GlobeLocation,
  previous: GlobeLocation
): Region[] {
  return REGIONS.filter((region) => {
    const isAhead = isNearCentreOf(region.location, target);
    const wasInView = isNearCentreOf(region.location, previous);
    return isAhead && wasInView;
  });
}

/** US East in front, or: the route from Europe to India in front. */
export function facingLineOf(facing: Facing) {
  if (facing.kind === 'region') {
    const name = regionOf(facing.id).name;
    return `${name} in front`;
  }
  const from = regionOf(facing.from).name;
  const to = regionOf(facing.to).name;
  return `the route from ${from} to ${to} in front`;
}

function shifted(value: number, amount: number, sign: Sign) {
  const change = amount * sign;
  const next = value + change;
  return Math.max(0, next);
}

function loadAfter(load: RegionLoad, rate: RunRate, sign: Sign): RegionLoad {
  return {
    runs: shifted(load.runs, 1, sign),
    tokens: shifted(load.tokens, rate.tokens, sign),
    cents: shifted(load.cents, rate.cents, sign),
  };
}

function withRun(
  state: ActivityState,
  region: RegionId,
  rate: RunRate,
  sign: Sign
): ActivityState {
  const load = loadAfter(state.loads[region], rate, sign);
  return { ...state, loads: { ...state.loads, [region]: load } };
}

export function handoffLineOf(handoff: Handoff) {
  const agent = AGENTS[handoff.agentId].name;
  const from = regionOf(handoff.from).name;
  const to = regionOf(handoff.to).name;
  return `${agent} handed a run from ${from} to ${to}`;
}

function facesRegion(facing: Facing, id: RegionId) {
  if (facing.kind !== 'region') {
    return false;
  }
  return facing.id === id;
}

/** Picking a region turns the globe to it, also when it is already picked and a hand-off turned the globe away. */
function selected(state: ActivityState, id: RegionId): ActivityState {
  const isPicked = state.selectedId === id;
  const isInFront = facesRegion(state.facing, id);
  if (isPicked && isInFront) {
    return state;
  }
  const facing: Facing = { kind: 'region', id };
  const notice = facingLineOf(facing);
  return { ...state, selectedId: id, facing, notice };
}

/** A run leaves one region for another: the globe turns to show both, and the arc draws itself. */
function handedOff(
  state: ActivityState,
  agentId: AgentId,
  from: RegionId,
  to: RegionId,
  rate: RunRate
): ActivityState {
  const left = withRun(state, from, rate, -1);
  const arrived = withRun(left, to, rate, 1);
  const handoff: Handoff = { id: state.nextId, agentId, from, to };
  const facing: Facing = { kind: 'route', from, to };
  const nextId = state.nextId + 1;
  const notice = handoffLineOf(handoff);
  return {
    ...arrived,
    lastHandoff: handoff,
    drawingId: handoff.id,
    facing,
    nextId,
    notice,
  };
}

export function reducer(
  state: ActivityState,
  action: ActivityAction
): ActivityState {
  switch (action.type) {
    case 'selected':
      return selected(state, action.id);
    case 'started':
      return withRun(state, action.region, action.rate, 1);
    case 'finished':
      return withRun(state, action.region, action.rate, -1);
    case 'handedOff':
      return handedOff(
        state,
        action.agentId,
        action.from,
        action.to,
        action.rate
      );
  }
}

export function totalRunsOf(state: ActivityState) {
  let total = 0;
  for (const region of REGIONS) {
    total += state.loads[region.id].runs;
  }
  return total;
}

